import { VecBase } from "./VecBase";
export class Vec2 extends VecBase {
    static ZERO = new Vec2(0, 0);
    static ONE = new Vec2(1, 1);
    static UNIT_X = new Vec2(1, 0);
    static UNIT_Y = new Vec2(0, 1);
    static NEG_X = new Vec2(-1, 0);
    static NEG_Y = new Vec2(0, -1);
    x;
    y;
    constructor(x, y) {
        super();
        this.x = x ?? 0;
        this.y = y ?? 0;
    }
    // Required methods
    clone() {
        return new Vec2(this.x, this.y);
    }
    add(v) {
        return new Vec2(this.x + v.x, this.y + v.y);
    }
    scale(s) {
        return new Vec2(s * this.x, s * this.y);
    }
    dot(v) {
        return this.x * v.x + this.y * v.y;
    }
    toString() {
        return `Vec2(${this.x.toFixed(3)}, ${this.y.toFixed(3)})`;
    }
    // Additional methods
    rotate(theta) {
        const x = this.x * Math.cos(theta) - this.y * Math.sin(theta);
        const y = this.x * Math.sin(theta) + this.y * Math.cos(theta);
        return new Vec2(x, y);
    }
    angle() {
        return Math.atan2(this.y, this.x);
    }
}
